        b.dirty=0;check(b.transferFluid(Fluids.LPG,0,123)==0&&b.dirty>0,"idle pipe fill marks dirty");b.dirty=0;check(b.transferFluid(Fluids.WATER,0,4)==4&&b.transferFluid(Fluids.LPG,1,4)==4&&b.dirty==0,"wrong type/pressure no dirty");
        b.power=4321;b.tenth=5;b.setting=1;b.isOn=true;CompoundTag saved=new CompoundTag();nbt(b,saved,false);var c=engine(l,10,Type.STEEL,Fluids.DIESEL,0);nbt(c,saved,true);check(c.power==4321&&c.tenth==5&&c.setting==1&&c.isOn&&c.tank.getFill()==123&&c.tank.getTankType()==Fluids.LPG&&!c.wasOn,"production NBT halfmB state roundtrip");
